// Writes data/credibility-results.js and documentation/CREDIBILITY.md: every validation rocket flown once nominally and N times with dispersed
// inputs, the real-mission cases, and the evidence counts the credibility scores use. The Credibility page reads the generated file so it
// opens instantly; its "Fly again" buttons recompute live. Re-run after any physics, vehicle or validation-data change:
//   node scripts/update-credibility.mjs            (24 dispersed flights per rocket, about 5 minutes)
//   N=8 node scripts/update-credibility.mjs        (quicker, wider error bars on the error bars)
import { writeFileSync, readFileSync, readdirSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { dispersionStudy, buildReport, VEHICLE_IDS, ROLES, LEVELS, SIM_DISPERSIONS, fmtRel } from '../src/core/credibility.js';
import { getValidationVehicle, VALIDATION_VEHICLES } from '../src/core/validation.js';
import { MISSION_CASES, runMissionCase } from '../src/core/mission-validation.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const N = Number(process.env.N ?? 24), SEED = Number(process.env.SEED ?? 1);
const only = process.argv.slice(2);

/** Only the metrics some row (or the outcome) uses: keeps the generated file small. */
function keepMetrics(id, m) {
  const V = getValidationVehicle(id), keys = new Set([...V.rows.map((r) => r.metric), 'maxAlt', 'reachedOrbit', 'peakPeriapsis']);
  const o = {};
  for (const k of keys) o[k] = m[k] == null || !Number.isFinite(m[k]) ? null : +m[k].toPrecision(7);
  return o;
}
const slimFlight = (id, f) => ({ ...f, metrics: keepMetrics(id, f.metrics) });

const studies = [];
for (const id of VEHICLE_IDS) {
  if (only.length && !only.includes(id)) continue;
  const t = Date.now();
  const s = await dispersionStudy(id, { n: N, seed: SEED });
  studies.push({ ...s, nominal: slimFlight(id, s.nominal), runs: s.runs.map((r) => slimFlight(id, r)) });
  console.log(`${id.padEnd(14)} nominal ${s.nominal.ok ? 'OK  ' : 'FAIL'}  dispersed ${s.runs.filter((r) => r.ok).length}/${s.runs.length} ok  (${((Date.now() - t) / 1000).toFixed(0)} s)`);
}
const missions = [];
for (const C of MISSION_CASES) {
  if (only.length && !only.includes(C.id)) continue;
  const t = Date.now();
  const r = await runMissionCase(C.id, { sync: true });
  missions.push({ C: { id: C.id, name: C.name }, rows: r.rows.map(({ id, label, metric, value, unit, tol, kind, source, url, note, sim, err, status }) => ({ id, label, metric, value, unit, tol, kind, group: 'mission', source, url, note, sim: sim == null ? null : +sim.toPrecision(8), err, status })) });
  console.log(`${C.id.padEnd(14)} ${r.summary.pass}/${r.summary.total} in band  (${((Date.now() - t) / 1000).toFixed(0)} s)`);
}

// evidence for the verification / management factors
const testDir = path.join(root, 'tests');
const testFiles = readdirSync(testDir).filter((f) => f.endsWith('.test.js'));
const unitTests = testFiles.reduce((s, f) => s + (readFileSync(path.join(testDir, f), 'utf8').match(/^\s*test\(/gm) ?? []).length, 0);
const analytic = missions.filter((m) => ['orbits', 'precession'].includes(m.C.id)).flatMap((m) => m.rows.filter((r) => r.kind === 'graded'));
const evidence = {
  unitTests, testFiles: testFiles.length,
  analyticPass: analytic.filter((r) => r.status === 'pass').length, analyticTotal: analytic.length,
  ci: existsSync(path.join(root, '.github/workflows/tests.yml')),
  estimatedInputs: VALIDATION_VEHICLES.reduce((s, V) => s + V.assumptions.filter((a) => /ESTIMATE|ASSUMED|TUNED|DERIVED/.test(a)).length, 0),
};

const date = new Date().toISOString().slice(0, 10);
const data = { generated: date, n: N, seed: SEED, studies, missions, evidence };
writeFileSync(path.join(root, 'data/credibility-results.js'), `// Generated by scripts/update-credibility.mjs (${date}, ${N} dispersed flights per rocket, seed ${SEED}). Do not edit by hand.\nexport const CREDIBILITY_RESULTS = ${JSON.stringify(data)};\n`);

// ---- documentation/CREDIBILITY.md ----
const rep = buildReport({ studies, missions, evidence });
const H = rep.headline;
const num = (v, u) => {
  if (v == null || !Number.isFinite(v)) return '–';
  if (u === 'm') return Math.abs(v) >= 1000 ? `${(v / 1000).toFixed(1)} km` : `${v.toFixed(0)} m`;
  if (u === 'N') return `${(v / 1e6).toFixed(2)} MN`;
  if (u === 'kg') return `${Math.round(v).toLocaleString('en-US')} kg`;
  if (u === 's' && v >= 3600) return `${(v / 3600).toFixed(2)} h`;
  return `${+v.toPrecision(4)} ${u}`.trim();
};
const pm = (v, s, u) => (s == null ? num(v, u) : `${num(v, u)} ± ${num(s, u)}`);
const L = [];
L.push('# Credibility of the ASTRA LAB simulator', '', `Generated by \`scripts/update-credibility.mjs\` on ${date} (${N} dispersed flights per rocket, seed ${SEED}). Shown in the app under **Study → Credibility**.`, '');
L.push('## Headline', '');
L.push(`* **${H.predictions.consistent} of ${H.predictions.total} independent predictions** agree with the real flight within the combined error bars (|z| ≤ 2); ${H.predictions.tension} are in tension (2 < |z| ≤ 3) and ${H.predictions.inconsistent} are inconsistent (|z| > 3).`);
L.push(`* ${H.notEvidence} other graded rows are calibration, guidance targets, mission-plan times, build checks or consistency checks. They are shown but **not counted** as evidence.`);
L.push(`* ${H.flights.ok} of ${H.flights.total} nominal rocket flights succeed. The old ±10 % band passes ${H.band.pass} of ${H.band.total} rows, which looks much better than the evidence is.`);
L.push(`* Median model-form error of the predictions (the part the error bars do not explain): ${H.medianModelForm == null ? '–' : `${(H.medianModelForm * 100).toFixed(1)} %`}.`, '');
L.push('## Failures and weak spots', '');
for (const f of H.failures) L.push(`* **${f.caseName}** (${f.severity}): ${f.what}.`);
L.push('', '## Credibility scores (simplified NASA-STD-7009A, self-assessed)', '', '| Factor | Level | Evidence | To raise it |', '|---|---|---|---|');
for (const f of rep.credibility.factors) L.push(`| ${f.name} | ${LEVELS[f.level]} | ${f.why} | ${f.next} |`);
L.push('', `**Use:** ${rep.credibility.use}`, '');
L.push('## Method', '', '* Published side: each number has a 1-sigma error bar and a role (`data/validation-uncertainty.js`).', '* Simulator side: the nominal flight, plus the spread of the same number over the dispersed flights. Dispersions (1 sigma):');
for (const d of SIM_DISPERSIONS) L.push(`  * ${d.label}: ${(d.sigma * 100).toFixed(1)} %. ${d.basis}`);
L.push('* z = (simulated − published) / sqrt(σ_sim² + σ_pub²). Model-form error = max(0, |d| − 2 σ_c).', '* Roles:');
for (const [k, r] of Object.entries(ROLES)) L.push(`  * \`${k}\`: ${r.why}${r.evidence ? ' **Counts as evidence.**' : ''}`);
L.push('');
for (const c of rep.cases) {
  L.push(`## ${c.name}`, '');
  if (c.kind === 'vehicle') L.push(`Nominal flight: **${c.outcome.ok ? 'success' : `FAILED (${c.outcome.reason})`}**. Dispersed: ${c.dispersed.ok} of ${c.dispersed.n} succeed (95 % interval ${Math.round(c.dispersed.ci[0] * 100)}–${Math.round(c.dispersed.ci[1] * 100)} %)${c.suborbital ? '' : `; ${c.dispersed.inOrbit} of ${c.dispersed.n} at least get into orbit`}.`, '');
  else L.push('The simulator side of this case has no error bar (it is not flown with dispersed inputs), so z uses the published error bar only.', '');
  L.push('| Row | Role | Published | Simulator | Error | z | Verdict |', '|---|---|---|---|---|---|---|');
  for (const r of c.rows) {
    const sim = r.binary ? `${r.sim == null ? '–' : r.sim ? 'yes' : 'no'} (p = ${r.p == null ? '–' : r.p.toFixed(2)})` : pm(r.sim, r.sigmaSim, r.unit);
    L.push(`| ${r.label} | ${ROLES[r.role]?.label ?? r.role} | ${r.binary ? 'yes' : pm(r.published, r.sigmaPub, r.unit)} | ${sim} | ${r.binary ? '–' : fmtRel(r.rel)} | ${r.z == null || !Number.isFinite(r.z) ? '–' : Math.abs(r.z) > 50 ? (r.z > 0 ? '> 50' : '< −50') : r.z.toFixed(1)} | ${r.kind === 'context' ? `${r.verdict} (context)` : r.verdict} |`);
  }
  L.push('');
}
writeFileSync(path.join(root, 'documentation/CREDIBILITY.md'), L.join('\n'));
console.log(`\nPredictions: ${H.predictions.consistent}/${H.predictions.total} consistent, ${H.predictions.tension} tension, ${H.predictions.inconsistent} inconsistent. Scores: ${rep.credibility.factors.map((f) => `${f.id} ${f.level}`).join(', ')}`);
